package com.acme.workers;

import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class AuditJobWorker {

    private static final Logger logger = Logger.getLogger(AuditJobWorker.class.getName());
    private final BlockingQueue<AuditTask> taskQueue;
    private final RoleValidator roleValidator;
    private final AuditLogWriter logWriter;

    public AuditJobWorker(BlockingQueue<AuditTask> taskQueue, RoleValidator roleValidator, AuditLogWriter logWriter) {
        this.taskQueue = taskQueue;
        this.roleValidator = roleValidator;
        this.logWriter = logWriter;
    }

    public void processNextTask() throws InterruptedException {
        AuditTask task = taskQueue.take();
        if (!roleValidator.hasPermission(task.getSubmittedBy(), "AUDIT_WRITE")) {
            logger.warning("Unauthorized task submission by: " + sanitizeForLog(task.getSubmittedBy()));
            return;
        }
        String sanitizedAction = sanitizeForLog(task.getAction());
        String headerLine = buildHeaderLine(task.getSubmittedBy(), task.getTargetResource());
        logWriter.writeEntry(headerLine, sanitizedAction, task.getTimestamp());
    }

    private String buildHeaderLine(String user, String resource) {
        // Encode user and resource for the structured log header
        String encodedUser = encodeHeaderValue(user);
        String encodedResource = encodeHeaderValue(resource);
        return "User=" + encodedUser + "|Resource=" + encodedResource;
    }

    private String encodeHeaderValue(String value) {
        // Remove null bytes and encode special characters including CR/LF
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '\0') continue;
            if (c == '|') {
                sb.append("%7C");
            } else if (c == '=') {
                sb.append("%3D");
            } else if (c == '\r') {
                sb.append("%0D");
            } else if (c == '\n') {
                sb.append("%0A");
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private String sanitizeForLog(String input) {
        // Sanitize the action field - remove control characters
        if (input == null) return "";
        return input.replaceAll("[\\x00-\\x1f\\x7f]", "");
    }

    public static class AuditTask {
        private final String submittedBy;
        private final String action;
        private final String targetResource;
        private final long timestamp;

        public AuditTask(String submittedBy, String action, String targetResource) {
            this.submittedBy = submittedBy;
            this.action = action;
            this.targetResource = targetResource;
            this.timestamp = System.currentTimeMillis();
        }

        public String getSubmittedBy() { return submittedBy; }
        public String getAction() { return action; }
        public String getTargetResource() { return targetResource; }
        public long getTimestamp() { return timestamp; }
    }

    public static class RoleValidator {
        private final Map<String, Set<String>> userPermissions;

        public RoleValidator(Map<String, Set<String>> userPermissions) {
            this.userPermissions = userPermissions;
        }

        public boolean hasPermission(String user, String permission) {
            Set<String> perms = userPermissions.get(user);
            return perms != null && perms.contains(permission);
        }
    }

    public static class AuditLogWriter {
        private final OutputStream outputStream;

        public AuditLogWriter(OutputStream outputStream) {
            this.outputStream = outputStream;
        }

        public synchronized void writeEntry(String header, String action, long timestamp) {
            try {
                // Write structured log entry with HTTP-style headers
                // Format: header fields followed by blank line and body
                String entry = "X-Audit-Header: " + header + "\r\n" +
                               "X-Audit-Timestamp: " + timestamp + "\r\n" +
                               "X-Audit-Action: " + action + "\r\n" +
                               "\r\n";
                outputStream.write(entry.getBytes(StandardCharsets.UTF_8));
                outputStream.flush();
            } catch (IOException e) {
                logger.severe("Failed to write audit entry: " + e.getMessage());
            }
        }
    }
}
